import test from 'node:test';
import assert from 'node:assert/strict';
import {initialState,project,arrange,loadScenario,compare,validate} from './model.js';
import {definition} from '../../../embed/definitions/lab-authority.js';
import {validateState} from '../../../embed/core/schema.js';
const fresh=()=>structuredClone(initialState);
test('local decisions fit local needs but coupled choices may fail to connect',()=>{const s=fresh(),r=project(s);assert.equal(r.localFit,6);assert.equal(r.onTime,6);assert.equal(r.compatible,0);assert.equal(r.finish,3);});
test('shared context changes compatibility with a visible local-fit tradeoff',()=>{const s=arrange(fresh(),'context'),r=project(s);assert.equal(r.compatible,3);assert.equal(r.localFit,3);assert.equal(r.finish,4);assert.equal(r.consultations,6);assert.equal(r.onTime,6);});
test('central authority shares a finite queue and local authority wins independent demand',()=>{const s=loadScenario(fresh(),'independent'),local=project(arrange(s,'local')),central=project(arrange(s,'central'));assert.equal(local.localFit,central.localFit);assert.equal(local.onTime,6);assert.equal(central.onTime,2);assert.equal(central.finish,7);assert.equal(central.wait,15);});
test('common needs remove the local-fit tradeoff',()=>{const s=loadScenario(fresh(),'common'),r=project(arrange(s,'context'));assert.equal(r.localFit,r.total);assert.equal(r.compatible,s.demand);});
test('permission adds desk work without adding information or overriding method',()=>{const s=fresh();s.approval=[true,true];const r=project(s);assert.equal(r.finish,7);assert.equal(r.compatible,0);assert.equal(r.localFit,6);assert.ok(r.decisions.every(d=>d.steps.length===2));assert.equal(r.onTime,3);});
test('information moves independently from decision power; missing knowledge uses fallback',()=>{const s=fresh();s.knowledge[1]=0;assert.equal(project(s).localFit,3);s.consultLocal[1]=true;assert.equal(project(s).localFit,6);assert.equal(project(s).decisions[1].ready,1);});
test('consequence ownership does not silently change the decision rule',()=>{const s=fresh(),a=project(s);s.consequences=[2,2];const b=project(s);assert.deepEqual(a.decisions.map(d=>d.method),b.decisions.map(d=>d.method));assert.equal(b.burdens[2].disconnected,6);});
test('comparison replays pinned policy on current external timing and needs',()=>{const pinned=arrange(fresh(),'central'),current=loadScenario(fresh(),'independent');current.deadline=9;const c=compare(current,pinned);assert.equal(c.state.deadline,9);assert.equal(c.result.onTime,6);assert.equal(c.state.coupled,false);assert.deepEqual(c.state.deciders,[2,2]);assert.equal(c.situationChanged,true);});
test('slots never overlap and approvals wait for their own decision',()=>{const s=arrange(fresh(),'central');s.deciders=[0,2];s.approval=[true,false];s.capacity=[2,1,2];const r=project(s);for(let role=0;role<3;role++)for(let slot=0;slot<s.capacity[role];slot++){const steps=r.decisions.flatMap(d=>d.steps).filter(x=>x.role===role&&x.slot===slot).sort((a,b)=>a.start-b.start);for(let i=1;i<steps.length;i++)assert.ok(steps[i].start>=steps[i-1].end);}for(const d of r.decisions)if(d.steps.length===2)assert.ok(d.steps[1].start>=d.steps[0].end);});
test('portable definition validates complete bounded states and renders both widths',()=>{validateState(definition,fresh());for(const width of [320,1100]){const v=definition.views.queues.render(fresh(),{width});assert.match(v.svg,/<svg/);assert.match(v.summary,/6\/6/);assert.doesNotMatch(v.svg,/NaN|undefined/);}for(const bad of [{...fresh(),demand:7},{...fresh(),knowledge:[0]},{...fresh(),capacity:[0,1,1]},{...fresh(),unknown:1}])assert.throws(()=>validate(bad));});
